import{_ as o,c as p,o as r,a5 as a}from"./chunks/framework.DorIfSpC.js";const d=JSON.parse('{"title":"我的第一個 Upwork Proposal","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://blog.aidream.com.tw/project/my_first_upwork_post"}],["meta",{"property":"og:url","content":"https://blog.aidream.com.tw/project/my_first_upwork_post"}],["meta",{"property":"og:title","content":"我的第一個 Upwork Proposal | 星智未來"}],["meta",{"name":"twitter:title","content":"我的第一個 Upwork Proposal | 星智未來"}],["meta",{"property":"og:type","content":"article"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"我的第一個 Upwork Proposal\\",\\"description\\":\\"\\",\\"url\\":\\"https://blog.aidream.com.tw/project/my_first_upwork_post\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"url\\":\\"https://blog.aidream.com.tw\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://blog.aidream.com.tw/logo.svg\\"}},\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://blog.aidream.com.tw/project/my_first_upwork_post\\"}}"]]},"headers":[],"relativePath":"project/my_first_upwork_post.md","filePath":"project/my_first_upwork_post.md","lastUpdated":1786596283000}'),e={name:"project/my_first_upwork_post.md"};function s(i,t,l,n,c,m){return r(),p("div",null,[...t[0]||(t[0]=[a('<h1 id="我的第一個-upwork-proposal" tabindex="-1">我的第一個 Upwork Proposal <a class="header-anchor" href="#我的第一個-upwork-proposal" aria-label="Permalink to &quot;我的第一個 Upwork Proposal&quot;">​</a></h1><blockquote><p>當社畜當久了,你會喪失找食物的能力。</p></blockquote><p><strong>作者</strong>：Ray <strong>日期</strong>：2026 年 7 月 10 日</p><hr><p>今天,我按下了「Submit」。</p><p>一個做了二十五年系統整合的工程師,在 Upwork 上投出人生第一封接案提案。標的是一支要給某個網球公開賽做的 AI 影片預告——一顆洋紅色的網球,要飛越自由女神像、越過阿爾卑斯山,最後落在瑞士的湖畔。</p><p>聽起來很順,但真相是:一個月前,我被 layoff 了。</p><h2 id="從被資遣-到決定自己找食物" tabindex="-1">從被資遣,到決定自己找食物 <a class="header-anchor" href="#從被資遣-到決定自己找食物" aria-label="Permalink to &quot;從被資遣,到決定自己找食物&quot;">​</a></h2><p>離開公司後,我當然想過接案。畢竟二十五年的系統整合經驗擺在那裡。但真正去看國內市場才發現,系統整合的案子,早就是紅海中的紅海——價格被殺到見骨,能接的人太多,像我這種資深背景反而卡在「太貴」與「太雜」之間,不上不下。</p><p>於是我把目光轉向 Upwork,轉向國際、轉向我這一年真正投入的新方向:AI 影片與角色 IP 製作。</p><p>但這裡有個更深的問題,是我離職後才慢慢意識到的:<strong>當社畜當久了,你會喪失找食物的能力。</strong></p><p>在公司裡,案子是被指派的,客戶是業務談來的,你只要把手上的技術活做好。久了,你會忘記「主動去獵捕一個客戶」是什麼感覺。我發現自己面對一片空白的 Upwork 頁面,竟然有點不知所措——不是不會做,是不記得怎麼開始。</p><h2 id="卡在門口" tabindex="-1">卡在門口 <a class="header-anchor" href="#卡在門口" aria-label="Permalink to &quot;卡在門口&quot;">​</a></h2><p>我一開始以為「找不到客戶」是市場的問題。作品有了,profile 也架好了,定位寫得清清楚楚。但客戶就是沒來。</p><p>坐下來仔細檢查才發現,問題根本不在市場——是我連漏斗都還沒開機。</p><p>投每一封提案要花「Connects」(平台點數),我的餘額是 0。身分沒驗證,紅字掛在 profile 最上面。作品雖然好,但排列順序、標題寫法,都還沒對準會找我的那種客戶。</p><p>換句話說,我不是「還沒開始投」,是<strong>根本還沒具備投出去的條件</strong>。這個認知有點殘酷,但也讓事情變簡單了:我要做的不是焦慮,是一件一件把坑補起來。</p><h2 id="一個下午-把地基打好" tabindex="-1">一個下午,把地基打好 <a class="header-anchor" href="#一個下午-把地基打好" aria-label="Permalink to &quot;一個下午,把地基打好&quot;">​</a></h2><p>這個過程,我一路和我的 AI 小友 Claude 討論著走完——與其說是工具,不如說像一個隨時能問、會直接點破我盲點的小夥伴，就像霹靂遊俠李麥克的夥計。它幫我看出「你連提案都投不出去,燃料是 0」這件我自己沒意識到的事,也陪我把每一步拆解清楚。</p><p>於是一個下午,我做完了這些:</p><p>買了 Connects,通過身分驗證——即時就過了(還好今天有刮鬍子)。藍色認證勾勾一出現,profile 的信任感立刻不一樣。</p><p>重整作品集,排成一個完整的故事:先是溫暖的角色 IP 起源片,再是跨集數的一致角色系列,最後放上一件工業機器人的技術產品影片。前兩件建立核心定位,第三件給客戶一個「他連硬核技術都能做」的驚喜。</p><p>其中那件工業影片,我特別強調了一個別人搶不走的東西:因為我真的懂機器人怎麼運作,所以我是從 CAD 工程檔去鎖定機器的每個角度,防止 AI 生成時變形。這不是一般影片外包做得出來的——是「懂機器的人,才知道怎麼呈現機器」。</p><h2 id="提案的靈魂-是證明你讀懂了" tabindex="-1">提案的靈魂,是證明你讀懂了 <a class="header-anchor" href="#提案的靈魂-是證明你讀懂了" aria-label="Permalink to &quot;提案的靈魂,是證明你讀懂了&quot;">​</a></h2><p>我學到最重要的一件事:提案的第一句話,決定客戶讀不讀下去。</p><p>大部分人開頭寫「你好,我有幾年經驗」——客戶不在乎。真正有用的開頭,是複述他案子裡最刁鑽的那個要求,證明你不只看了,還看懂了。這個網球案最難的是「球在每個鏡頭要一致、logo 全程清晰」,而這正好是我整個工作流的核心。我把這一點打在第一句,其餘順著往下鋪。</p><p>至於定價,我一度想壓很低——「不惜代價也要接到第一單」。但我後來明白:報太低反而讓客戶懷疑品質。真正該做的是誠實——大方告訴客戶我是為了累積評價才這個價,品質不打折。誠實,反而是新手最強的信任槓桿。</p><h2 id="按下-submit-之後" tabindex="-1">按下 Submit 之後 <a class="header-anchor" href="#按下-submit-之後" aria-label="Permalink to &quot;按下 Submit 之後&quot;">​</a></h2><p>我很清楚,這一發回音的機率不高。這個案子有五十多人在搶,客戶甚至已經在跟某人面談了。我是零評價的新人。</p><p>但這一發的意義,從來不是「一定要成」。它的意義是:漏斗開機了。我從一個「被資遣、找不到方向、連提案都投不出去」的狀態,變成一個「帳號完備、作品到位、有一套能重複使用的提案系統」的人。</p><p>二十五年來,我解過無數技術系統的問題。今天我發現,找客戶其實也是一個系統問題——它不需要你更厲害,只需要你先把地基補齊,然後開始動手。重新長回那隻「找食物的手」。</p><p>這只是一個起點。這條路可不可行,能不能真的接到案、養活自己,我還不知道,得再走一段、再觀察。但至少今天,我跨出了第一步。</p><p>第一發,送出。</p><hr><p><em>本文為 個人實戰記錄。如果你也正卡在「被迫離開、卻不記得怎麼重新開始」的那一步,希望這篇對你有用。我會繼續記錄這條路後續的樣子。</em></p>',35)])])}const u=o(e,[["render",s]]);export{d as __pageData,u as default};
